bind(
        stream: UnixStream,
        peer: LearningIterationEvidencePeerV1,
        original_head_pidfd: OwnedFd,
        config: ArtifactHeadSigningConfigV1,
        timeout: Duration,
        lifetime: Duration,
        origin: Origin,
    ) -> Result<Self, Error> {
        let started = now()?;
        require_peer(&peer, &config.signer_id)?;
        config.authenticate_current(started)?;
        let binding = config.binding()?;
        let channel = original_owner_command_channel_v1(
            stream,
            AgentdRootAuthorityPeer {
                pid: peer.pid,
                boot_id: peer.boot_id,
                process_start_ticks: peer.process_start_ticks,
            },
            peer.uid,
            original_head_pidfd,
            timeout,
            lifetime,
        )?;
        channel.check_peer_lifetime()?;
        let initial_at = fresh(started)?;
        config.authenticate_current(initial_at)?;
        Ok(Self {
            channel,
            config,
            binding,
            initial_at,
            origin,
        })
    }

sign_original_registry(
        self,
        prepared: OriginalArtifactPreparedPublicationV1,
        cancelled: Arc<AtomicBool>,
    ) -> Result<
        (
            OriginalArtifactPreparedPublicationV1,
            SignedCurrentArtifactHeadV1,
        ),
        Error,
    > {
        if !matches!(&self.origin, Origin::Fresh) {
            return Err(Error::ReadbackRequired);
        }
        let original = prepared
            .registry_durable()
            .encode_for_original_head_source(&self.config)?;
        let claims = UntrustedArtifactRegistryDurableV1::decode(&original, &self.config)?;
        claims.require_unsigned_phase()?;


        let signed = self.exchange(wire::Action::Sign, claims, cancelled).await?;
        Ok((prepared, signed))
    }

read_original_head(
        self,
        observed: &OriginalArtifactRegistryDurableV1,
    ) -> Result<SignedCurrentArtifactHeadV1, Error> {
        let bytes = observed.encode_for_original_head_source(&self.config)?;
        let source = UntrustedArtifactRegistryDurableV1::decode(&bytes, &self.config)?;
        self.exchange(
            wire::Action::Readback,
            source,
            Arc::new(AtomicBool::new(false)),
        )
        .await
    }

exchange(
        mut self,
        action: wire::Action,
        source: UntrustedArtifactRegistryDurableV1,
        cancelled: Arc<AtomicBool>,
    ) -> Result<SignedCurrentArtifactHeadV1, Error> {
        let started = now()?;
        if started < self.initial_at {
            return Err(Error::CommitUncertain);
        }
        source.authenticate_current(&self.config, started)?;
        let request = wire::Request::new(wire::Purpose::Head, action, 1, self.binding)?;
        let encoded = request.encode();
        let abandoned = Arc::new(AtomicBool::new(false));
        let waiting = QueueFence(Arc::clone(&abandoned));
        let (channel, bytes) = tokio::task::spawn_blocking(move || {
            if abandoned.load(Ordering::Acquire) || cancelled.load(Ordering::Acquire) {
                return Err(Error::CommitUncertain);
            }
            self.channel.check_peer_lifetime()?;
            if abandoned.load(Ordering::Acquire) || cancelled.load(Ordering::Acquire) {
                return Err(Error::CommitUncertain);
            }
            let bytes = self
                .channel
                .request(&encoded)
                .map_err(|_| Error::CommitUncertain)?;
            Ok::<_, Error>((self, bytes))
        })
        .await
        .map_err(|_| Error::CommitUncertain)??;
        drop(waiting);
        let payload = request.read_response(&bytes).map_err(|error| {
            if action == wire::Action::Sign {
                Error::CommitUncertain
            } else {
                error
            }
        })?;
        let signed = decode_artifact_head_bytes_v1(payload)?;
        channel.channel.check_peer_lifetime()?;
        let current = fresh(started)?;
        channel
            .config
            .verify_original_head(&source, &signed, current)?;
        if let Origin::Readonly(Some(expected)) = channel.origin
            && expected != signed
        {
            return Err(Error::CommitUncertain);
        }
        Ok(signed)
    }

serve_commands(
        self: &Arc<Self>,
        stream: UnixStream,
        consumer: LearningIterationEvidencePeerV1,
        original_consumer_pidfd: OwnedFd,
        timeout: Duration,
        lifetime: Duration,
    ) -> Result<u64, Error> {
        require_peer(&consumer, &self.source.config.writer_lease.producer_id)?;
        let permit = Arc::clone(&self.connections)
            .try_acquire_owned()
            .map_err(|_| Error::Busy)?;

        let mut channel = original_owner_command_channel_v1(
            stream,
            AgentdRootAuthorityPeer {
                pid: consumer.pid,
                boot_id: consumer.boot_id,
                process_start_ticks: consumer.process_start_ticks,
            },
            consumer.uid,
            original_consumer_pidfd,
            timeout,
            lifetime,
        )?;
        let binding = self.source.config.binding()?;
        let original = Arc::clone(self);
        let cancelled = Arc::new(AtomicBool::new(false));
        let waiting = QueueFence(Arc::clone(&cancelled));
        let result = tokio::task::spawn_blocking(move || {
            let _permit = permit;
            for nonce in 1..=128 {
                if cancelled.load(Ordering::Acquire) {
                    return Err(Error::Unavailable);
                }
                let mut failure = None;
                let exchanged = channel.exchange(|bytes| {
                    if cancelled.load(Ordering::Acquire) {
                        return Err(HostIssuerTransportError::Unavailable);
                    }
                    let result = (|| {
                        let started = now()?;
                        let request =
                            wire::Request::decode(bytes, wire::Purpose::Head, nonce, binding)?;
                        original.source.config.authenticate_current(started)?;
                        let response = match request.action {
                            wire::Action::Sign => original.sign_original(&cancelled),
                            wire::Action::Readback => original.read_original(&cancelled),
                        };
                        original
                            .source
                            .config
                            .authenticate_current(fresh(started)?)?;
                        match response {
                            Ok(signed) => request.response(wire::Status::Completed, &signed),
                            Err(Error::Missing) => request.response(wire::Status::Missing, &[]),
                            Err(Error::Pending) => request.response(wire::Status::Pending, &[]),
                            Err(Error::ReadbackRequired) => {
                                request.response(wire::Status::ReadbackRequired, &[])
                            }
                            Err(error) => Err(error),
                        }
                    })();
                    result.map_err(|error| {
                        failure = Some(error);
                        HostIssuerTransportError::InvalidRequest
                    })
                });
                match exchanged {
                    Ok(true) => {}
                    Ok(false) => return Ok(nonce - 1),
                    Err(error) => return Err(failure.unwrap_or(Error::Transport(error))),
                }
            }
            Err(Error::Unavailable)
        })
        .await
        .map_err(|_| Error::CommitUncertain)?;
        drop(waiting);
        result
    }

