        let waiting = QueueFence(Arc::clone(&cancelled));
        let result = tokio::task::spawn_blocking(move || original.read_current_in_lane(&cancelled))
            .await
            .map_err(|_| Error::Unavailable)?;
        drop(waiting);
        result
