read_response<'a>(&self, bytes: &'a [u8]) -> Result<&'a [u8], Error> {
        if bytes.len() < HEADER + 5 || bytes.len() > MAX_BYTES || bytes[..HEADER] != self.encode() {
            return Err(Error::Binding(                                 ));
        }
        let length =
            u32::from_be_bytes(bytes[51..55].try_into().map_err(|_| Error::Unavailable)?) as usize;
        if bytes.len() != HEADER + 5 + length {
            return Err(Error::Unavailable);
        }
        match bytes[50] {
            1 if length > 0 => Ok(&bytes[55..]),
            2 if length == 0 => Err(Error::Missing),
            3 if length == 0 => Err(Error::Pending),
            4 if length == 0 => Err(Error::Unavailable),
            5 if length == 0 => Err(Error::ReadbackRequired),
            _ => Err(Error::Binding(                                   )),
        }
    }

