new(
        purpose: Purpose,
        action: Action,
        nonce: u64,
        binding: Digest32,
    ) -> Result<Self, Error> {
        if nonce == 0
            || nonce > 128
            || binding.is_zero()
            || purpose == Purpose::Registry && action != Action::Readback
        {
            return Err(Error::Binding(                                         ));
        }
        Ok(Self {
            purpose,
            action,
            nonce,
            binding,
        })
    }

encode(&self) -> Vec<u8> {
        let mut bytes = MAGIC.to_vec();
        bytes.push(self.purpose as u8);
        bytes.push(self.action as u8);
        bytes.extend_from_slice(&self.nonce.to_be_bytes());
        bytes.extend_from_slice(self.binding.as_array());
        bytes
    }

decode(
        bytes: &[u8],
        purpose: Purpose,
        nonce: u64,
        binding: Digest32,
    ) -> Result<Self, Error> {
        if bytes.len() != HEADER
            || bytes.get(..8) != Some(MAGIC.as_slice())
            || bytes[8] != purpose as u8
        {
            return Err(Error::Binding(                                 ));
        }
        let action = match bytes[9] {
            1 => Action::Readback,
            2 => Action::Sign,
            _ => return Err(Error::Binding(                          )),
        };
        let observed_nonce =
            u64::from_be_bytes(bytes[10..18].try_into().map_err(|_| Error::Unavailable)?);
        let observed_binding =
            Digest32::from_array(bytes[18..50].try_into().map_err(|_| Error::Unavailable)?);
        if observed_nonce != nonce || observed_binding != binding {
            return Err(Error::Binding(                                          ));
        }
        Self::new(purpose, action, nonce, binding)
    }

response(&self, status: Status, payload: &[u8]) -> Result<Vec<u8>, Error> {
        if status != Status::Completed && !payload.is_empty() {
            return Err(Error::Binding(                                          ));
        }
        let length = HEADER
            .checked_add(5)
            .and_then(|n| n.checked_add(payload.len()))
            .ok_or(Error::Unavailable)?;
        if length > MAX_BYTES || status == Status::Completed && payload.is_empty() {
            return Err(Error::Binding(
                                                             ,
            ));
        }
        let mut bytes = self.encode();
        bytes.push(status as u8);
        bytes.extend_from_slice(&(payload.len() as u32).to_be_bytes());
        bytes.extend_from_slice(payload);
        Ok(bytes)
    }

binding(&self) -> Result<Digest32, Error> {
        let verifier = ArtifactOwnerVerifierV1::new(self.trust.clone())?;
        let mut bytes = b                                        .to_vec();
        bytes.extend_from_slice(verifier.trust_digest().as_array());
        bytes.extend_from_slice(self.storage_binding.as_array());
        bytes.extend_from_slice(self.writer_lease_digest().as_array());
        bytes.extend_from_slice(
            crate::publication::digest_intent(
                &self.publication.operation_id,
                &self.publication.admission,
                self.publication.expected_registry_predecessor_head,
            )
            .as_array(),
        );
        push_id(&mut bytes, &self.signer_id);
        bytes.extend_from_slice(&self.authority_epoch.to_be_bytes());
        bytes.extend_from_slice(&self.signature_expires_at.to_be_bytes());
        Ok(Digest32::of_bytes(&bytes))
    }

writer_lease_digest(&self) -> Digest32 {
        let mut bytes = self.writer_lease.signing_bytes();
        bytes.extend_from_slice(&self.writer_lease.signature);
        Digest32::of_bytes(&bytes)
    }

authenticate_current(&self, now: u64) -> Result<(), Error> {
        let verifier = ArtifactOwnerVerifierV1::new(self.trust.clone())?;
        let writer = verifier.verify_writer_lease(&self.writer_lease, now)?;
        let manifest = &self.publication.admission.validated_manifest.manifest;
        if self.storage_binding.is_zero()
            || manifest.producer_id != writer.producer_id
            || self.publication.admission.withdrawal_scope_digest
                != self.trust.withdrawal_scope_digest
            || self.signer_id == writer.producer_id
            || self.signature_expires_at < now
            || self.signature_expires_at > self.writer_lease.expires_at
            || self.signature_expires_at > manifest.expires_at
            || self.authority_epoch < self.trust.minimum_authority_epoch
        {
            return Err(Error::WriterLeaseContext);
        }
        verify_artifact_admission_v3(
            &self.publication.admission,
            self.publication.admission.withdrawal_head_digest,
            now,
        )
        .map_err(|_| Error::CheckpointMismatch)?;
        let signer = verifier
            .head_signers
            .get(&self.signer_id)
            .ok_or(Error::UnknownSigner)?;
        if self.signature_expires_at > signer.expires_at
            || signer
                .revoked_at
                .is_some_and(|at| self.signature_expires_at >= at)
            || self.trust.writer_signers.iter().any(|writer| {
                writer.signer_id == signer.signer_id || writer.verifying_key == signer.verifying_key
            })
        {
            return Err(Error::SignerContext);
        }
        verify_signer_context(
            signer,
            Digest32::of_bytes(&signer.verifying_key),
            self.authority_epoch,
            now,
            now,
                                true,
        )
    }

require_registered_key(&self, verifying_key: &[u8; 32], now: u64) -> Result<(), Error> {
        self.authenticate_current(now)?;
        let signer = self
            .trust
            .head_signers
            .iter()
            .find(|entry| entry.signer_id == self.signer_id)
            .ok_or(Error::UnknownSigner)?;
        if &signer.verifying_key != verifying_key {
            return Err(Error::InvalidKey);
        }
        Ok(())
    }

unsigned_head(
        &self,
        source: &UntrustedArtifactRegistryDurableV1,
        issued_at: u64,
    ) -> Result<SignedCurrentArtifactHeadV1, Error> {
        source.authenticate_current(self, issued_at)?;
        let generation = self.expected_generation(source)?;
        let signer = self
            .trust
            .head_signers
            .iter()
            .find(|entry| entry.signer_id == self.signer_id)
            .ok_or(Error::UnknownSigner)?;
        Ok(SignedCurrentArtifactHeadV1 {
            withdrawal_scope_digest: self.trust.withdrawal_scope_digest,
            binding: self.storage_binding,
            witness: RegistryHeadWitnessV1 {
                registry_id: self.trust.registry_id.clone(),
                generation,
                head_digest: source.registry_receipt().head_digest,
                predecessor_head_digest: self.publication.expected_registry_predecessor_head,
                authority_epoch: self.authority_epoch,
                signer_id: self.signer_id.clone(),
                signing_key_digest: Digest32::of_bytes(&signer.verifying_key),
                issued_at,
                expires_at: self.signature_expires_at,
            },
            signature: [0; 64],
        })
    }

verify_original_head(
        &self,
        source: &UntrustedArtifactRegistryDurableV1,
        signed: &SignedCurrentArtifactHeadV1,
        now: u64,
    ) -> Result<(), Error> {
        source.authenticate_current(self, now)?;
        if signed.witness.issued_at > now {
            return Err(Error::CurrentHeadContext);
        }


        let signer = self
            .trust
            .head_signers
            .iter()
            .find(|entry| entry.signer_id == self.signer_id)
            .ok_or(Error::UnknownSigner)?;
        if signed.withdrawal_scope_digest != self.trust.withdrawal_scope_digest
            || signed.binding != self.storage_binding
            || signed.witness.registry_id != self.trust.registry_id
            || signed.witness.generation != self.expected_generation(source)?
            || signed.witness.head_digest != source.registry_receipt().head_digest
            || signed.witness.predecessor_head_digest
                != self.publication.expected_registry_predecessor_head
            || signed.witness.authority_epoch != self.authority_epoch
            || signed.witness.signer_id != self.signer_id
            || signed.witness.signing_key_digest != Digest32::of_bytes(&signer.verifying_key)
            || signed.witness.expires_at != self.signature_expires_at
        {
            return Err(Error::CurrentHeadContext);
        }
        if let Some(current) = source.current_head()
            && current.witness.head_digest == source.registry_receipt().head_digest
            && current != signed
        {
            return Err(Error::CurrentHeadConflict);
        }
        let verifier = ArtifactOwnerVerifierV1::new(self.trust.clone())?;
        verifier.verify_signed_head(
            signed,
            &RegistryHeadRequirementV1 {
                registry_id: self.trust.registry_id.clone(),
                minimum_generation: signed.witness.generation,
                expected_predecessor_head_digest: self
                    .publication
                    .expected_registry_predecessor_head,
                minimum_authority_epoch: self.trust.minimum_authority_epoch,
                now,
            },
                                       true,
        )?;
        Ok(())
    }

expected_generation(
        &self,
        source: &UntrustedArtifactRegistryDurableV1,
    ) -> Result<Generation, Error> {
        match source.current_head() {
            Some(current)
                if current.witness.head_digest == source.registry_receipt().head_digest =>
            {
                Ok(current.witness.generation)
            }
            Some(current)
                if current.witness.head_digest
                    == self.publication.expected_registry_predecessor_head =>
            {
                if self.authority_epoch < current.witness.authority_epoch {
                    return Err(Error::SignerContext);
                }
                current
                    .witness
                    .generation
                    .next()
                    .map_err(|_| Error::CurrentHeadContext)
            }
            None if self.publication.expected_registry_predecessor_head
                == self.trust.genesis_predecessor_head_digest =>
            {
                Ok(self.trust.minimum_registry_generation)
            }
            Some(_) | None => Err(Error::CurrentHeadConflict),
        }
    }

read_original_publication_checkpoints(
        &self,
        operation_id: &StableId,
    ) -> Result<Vec<ArtifactOwnerPublicationCheckpointV1>, ArtifactOwnerHostError> {
        let mut observed = Vec::new();
        let mut missing_seen = false;
        let mut invariant = None;
        for phase in ordered_phases() {
            let path = self.checkpoint_path(operation_id, phase);
            if !path.exists() {
                missing_seen = true;
                continue;
            }
            if missing_seen {
                return Err(ArtifactOwnerHostError::CheckpointGap);
            }
            let checkpoint = decode_checkpoint(&read_small_record(&path, MAX_SMALL_RECORD_BYTES)?)?;
            if checkpoint.operation_id != *operation_id || checkpoint.phase != phase {
                return Err(ArtifactOwnerHostError::CheckpointMismatch);
            }
            let key = (
                checkpoint.intent_digest,
                checkpoint.admission_digest,
                checkpoint.withdrawal_scope_digest,
                checkpoint.expected_registry_predecessor_head,
            );
            if invariant.is_some_and(|value| value != key) {
                return Err(ArtifactOwnerHostError::CheckpointMismatch);
            }
            invariant = Some(key);
            observed.push(checkpoint);
        }
        Ok(observed)
    }

read_original_registry_durable(
        &self,
        context: &OriginalArtifactPublicationContextV1,
        withdrawals: &DatasetWithdrawalRegistry,
        binding: Digest32,
        clock: &impl Fn() -> Result<u64, Error>,
    ) -> Result<OriginalArtifactRegistryDurableV1, Error> {
        let started = clock()?;
        let writer = self.require_current_writer(started)?;
        let withdrawals_before = withdrawals.snapshot();
        validate_artifact_publication_v3(&context.admission, withdrawals, started)
            .map_err(ArtifactPublicationError::from)?;
        let before_records = self.read_original_publication_checkpoints(&context.operation_id)?;
        let before = before_records.last().cloned().ok_or(Error::NoCheckpoint)?;


        for checkpoint in &before_records {
            if checkpoint.admission_digest != context.admission.admission_digest
                || checkpoint.withdrawal_scope_digest != context.admission.withdrawal_scope_digest
                || checkpoint.withdrawal_head_digest != context.admission.withdrawal_head_digest
                || checkpoint.expected_registry_predecessor_head
                    != context.expected_registry_predecessor_head
                || checkpoint.original_writer_lease_digest != writer.lease_digest
                || checkpoint.authority.grants_any()
                || context.admission.validated_manifest.manifest.producer_id != writer.producer_id
            {
                return Err(Error::Context);
            }
            ArtifactPublicationTransactionV1::from_snapshot(
                ArtifactPublicationTransactionSnapshotV1 {
                    intent: ArtifactPublicationIntentV1 {
                        operation_id: context.operation_id.clone(),
                        admission: context.admission.clone(),
                        expected_registry_predecessor_head: context
                            .expected_registry_predecessor_head,
                        intent_digest: checkpoint.intent_digest,
                    },
                    phase: checkpoint.phase,
                    registry_receipt: checkpoint.registry_receipt,
                    witness_receipt: checkpoint.witness_receipt,
                    acknowledged_at: checkpoint.acknowledged_at,
                    state_digest: checkpoint.state_digest,
                },
            )?;
        }
        if matches!(
            before.phase,
            ArtifactPublicationPhaseV1::Prepared | ArtifactPublicationPhaseV1::PayloadDurable
        ) {
            return Err(Error::Pending(before.phase));
        }
        let receipt = before.registry_receipt.ok_or(Error::Context)?;
        if receipt.binding != binding {
            return Err(Error::Context);
        }
        let (current_before, current_registry_before) =
            self.read_preparation_current(binding, started)?;
        let registry = read_registry_snapshot(
            File::open(self.registry_snapshot_path(receipt))
                .map_err(ArtifactOwnerHostError::from)?,
            receipt,
        )
        .map_err(ArtifactOwnerHostError::from)?;
        let mut predecessor_snapshot = registry.snapshot();
        let last = predecessor_snapshot.records.pop().ok_or(Error::Context)?;
        if last.predecessor_chain_digest != context.expected_registry_predecessor_head {
            return Err(Error::Context);
        }
        predecessor_snapshot.head_digest = context.expected_registry_predecessor_head;
        let predecessor = ArtifactRegistry::from_snapshot(predecessor_snapshot)
            .map_err(ArtifactOwnerHostError::from)?;
        let mut transaction = ArtifactPublicationTransactionV1::begin(
            context.operation_id.clone(),
            context.admission.clone(),
            withdrawals,
            &predecessor,
            context.expected_registry_predecessor_head,
            started,
        )?;
        if last.event != original_registration_event(&transaction)? {
            return Err(Error::Context);
        }
        let manifest = &context.admission.validated_manifest.manifest;
        let path = self.root.join(          ).join(format!(
                       ,
            manifest.artifact_id, manifest.bytes_digest
        ));
        let payload = read_candidate_payload(
            File::open(&path).map_err(ArtifactOwnerHostError::from)?,
            &registry,
            &manifest.artifact_id,
        )
        .map_err(ArtifactOwnerHostError::from)?;
        transaction.record_payload_durable(Digest32::of_bytes(&payload), payload.len() as u64)?;
        transaction.record_registry_durable(&registry, receipt, withdrawals, started)?;
        let current_head = current_before
            .as_ref()
            .map(|value| value.witness.head_digest);
        let current_is_parent = current_registry_before.snapshot().head_digest
            == context.expected_registry_predecessor_head
            && (current_before.is_some()
                || context.expected_registry_predecessor_head
                    == self.verifier.trust.genesis_predecessor_head_digest);
        if !current_is_parent && current_head != Some(receipt.head_digest) {
            return Err(Error::Context);
        }
        if matches!(
            before.phase,
            ArtifactPublicationPhaseV1::WitnessDurable | ArtifactPublicationPhaseV1::Acknowledged
        ) {
            let signed = current_before.as_ref().ok_or(Error::Context)?;
            if signed.witness.head_digest != receipt.head_digest {
                return Err(Error::Context);
            }
            let requirement = self.preparation_head_requirement(signed, started);
            let witness_receipt = before.witness_receipt.ok_or(Error::Context)?;
            let witness_path = self.root.join(           ).join(format!(
                               ,
                signed.witness.generation.get(),
                witness_receipt.witness_digest
            ));
            let actual = read_registry_head_witness(
                File::open(witness_path).map_err(ArtifactOwnerHostError::from)?,
                witness_receipt,
                &requirement,
            )
            .map_err(ArtifactOwnerHostError::from)?;
            if actual != signed.witness {
                return Err(Error::Context);
            }
            transaction.record_witness_durable(
                &actual,
                &requirement,
                witness_receipt,
                withdrawals,
                started,
            )?;
            if let Some(acknowledged_at) = before.acknowledged_at {
                transaction.acknowledge(withdrawals, acknowledged_at)?;
            }
        }
        if checkpoint_from_snapshot(&transaction.snapshot(), writer.lease_digest) != before {
            return Err(Error::Context);
        }


        let registry_after = read_registry_snapshot(
            File::open(self.registry_snapshot_path(receipt))
                .map_err(ArtifactOwnerHostError::from)?,
            receipt,
        )
        .map_err(ArtifactOwnerHostError::from)?;
        let payload_after = read_candidate_payload(
            File::open(path).map_err(ArtifactOwnerHostError::from)?,
            &registry_after,
            &manifest.artifact_id,
        )
        .map_err(ArtifactOwnerHostError::from)?;
        let (current_after, current_registry_after) =
            self.read_preparation_current(binding, started)?;
        let after_records = self.read_original_publication_checkpoints(&context.operation_id)?;
        let after = after_records.last().cloned().ok_or(Error::NoCheckpoint)?;
        if before_records != after_records
            || registry.snapshot() != registry_after.snapshot()
            || payload != payload_after
            || current_before != current_after
            || current_registry_before.snapshot() != current_registry_after.snapshot()
            || withdrawals_before != withdrawals.snapshot()
        {
            return Err(Error::ChangedDuringRead);
        }
        let fresh = clock()?;
        if fresh < started {
            return Err(Error::Clock);
        }
        let writer_after = self.require_current_writer(fresh)?;
        if writer_after.lease_digest != writer.lease_digest {
            return Err(Error::ChangedDuringRead);
        }
        validate_artifact_publication_v3(&context.admission, withdrawals, fresh)
            .map_err(ArtifactPublicationError::from)?;
        if let Some(signed) = &current_after {
            self.verifier.verify_signed_head(
                signed,
                &self.preparation_head_requirement(signed, fresh),
                                           true,
            )?;
        }


        Ok(OriginalArtifactRegistryDurableV1 {
            checkpoint: after,
            registry: registry_after.snapshot(),
            registry_receipt: receipt,
            current: current_after,
            writer_lease: self.lease.clone(),
            trust_digest: self.verifier.trust_digest(),
            observed_unix_millis: fresh,
        })
    }

preparation_head_requirement(
        &self,
        signed: &SignedCurrentArtifactHeadV1,
        now: u64,
    ) -> RegistryHeadRequirementV1 {
        RegistryHeadRequirementV1 {
            registry_id: self.verifier.trust.registry_id.clone(),
            minimum_generation: signed.witness.generation,
            expected_predecessor_head_digest: signed.witness.predecessor_head_digest,
            minimum_authority_epoch: self.verifier.trust.minimum_authority_epoch,
            now,
        }
    }

read_preparation_current(
        &self,
        binding: Digest32,
        now: u64,
    ) -> Result<(Option<SignedCurrentArtifactHeadV1>, ArtifactRegistry), ArtifactOwnerHostError>
    {
        let Some(head) = self.discover_current_head(now)? else {
            return Ok((None, ArtifactRegistry::new()));
        };
        let current = self.current_registry_view_bounded(now)?;
        if current.receipt().binding != binding
            || current.receipt().head_digest != head.signed.witness.head_digest
            || current.witness_digest() != head.witness_digest
            || current.trust_digest() != head.trust_digest
        {
            return Err(ArtifactOwnerHostError::CurrentHeadConflict);
        }
        Ok((Some(head.signed), current.registry().clone()))
    }
